using AISmartLearning.API.Contracts;using AISmartLearning.API.Data;using AISmartLearning.API.Models;using AISmartLearning.API.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AISmartLearning.API.Controllers;
[ApiController][Route("api/auth")] public sealed class AuthController(AppDbContext db,IPasswordHasher<User> hasher,JwtTokenService tokens,InteractionLogService logs):ControllerBase {
[AllowAnonymous][HttpPost("login")] public async Task<ActionResult<LoginResponse>> Login(LoginRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Email)||string.IsNullOrWhiteSpace(r.Password))return BadRequest(new{message="Email and password are required."});var u=await db.Users.Include(x=>x.Role).SingleOrDefaultAsync(x=>x.Email==r.Email.Trim().ToLower(),ct);if(u is null||!u.IsActive||hasher.VerifyHashedPassword(u,u.PasswordHash,r.Password)==PasswordVerificationResult.Failed)return Unauthorized(new{message="Invalid email or password."});var(t,e)=tokens.Create(u);await logs.Write(u.UserId,"Login","Successful login",null,ct);return Ok(new LoginResponse(t,e,new UserSummary(u.UserId,u.FullName,u.Email,u.Role!.RoleName,u.IsActive)));}
[Authorize][HttpGet("me")] public async Task<IActionResult> Me(CancellationToken ct){var id=InteractionLogService.UserId(User);var u=await db.Users.Include(x=>x.Role).SingleOrDefaultAsync(x=>x.UserId==id&&x.IsActive,ct);return u is null?Unauthorized():Ok(new UserSummary(u.UserId,u.FullName,u.Email,u.Role!.RoleName,u.IsActive));}
[Authorize(Roles="Admin")][HttpPost("register")] public async Task<IActionResult> Register(RegisterRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.FullName)||string.IsNullOrWhiteSpace(r.Email)||r.Password.Length<10)return BadRequest(new{message="Name and email are required; password must be at least 10 characters."});var email=r.Email.Trim().ToLowerInvariant();if(await db.Users.AnyAsync(x=>x.Email==email,ct))return Conflict(new{message="Email already exists."});var roleName=r.Role.Trim();if(!new[]{"Admin","Teacher","Student"}.Contains(roleName,StringComparer.OrdinalIgnoreCase))return BadRequest(new{message="Role must be Admin, Teacher, or Student."});var role=await db.Roles.SingleAsync(x=>x.RoleName==roleName,ct);var u=new User{FullName=r.FullName.Trim(),Email=email,RoleId=role.RoleId,Role=role};u.PasswordHash=hasher.HashPassword(u,r.Password);db.Users.Add(u);await db.SaveChangesAsync(ct);await logs.Write(InteractionLogService.UserId(User),"UserCreated",$"Created user {email} with role {roleName}",null,ct);return Ok(new UserSummary(u.UserId,u.FullName,u.Email,role.RoleName,u.IsActive));}
}